int[] parent;
int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
int kruskal(int n, int[][] edges) {    // each edge is {weight, u, v}
    parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    Arrays.sort(edges, (a, b) -> Integer.compare(a[0], b[0]));
    int total = 0, used = 0;
    for (int[] e : edges) {
        int ru = find(e[1]), rv = find(e[2]);
        if (ru != rv) { parent[ru] = rv; total += e[0]; if (++used == n - 1) break; }
    }
    return total;
}

